import { afterEach, beforeEach, expect, it, vi } from 'vitest';
import Database from 'better-sqlite3';
import { schema } from '../database/schema';
import { runMigrations } from '../database/migrate';
import { setPushSender, startOperatorDigest } from '../services/operator-push';

let db: Database.Database;
const alerts: string[] = [];
const sender = {
  requestApproval: vi.fn(async () => {}),
  broadcastAlert: vi.fn(async (t: string) => { alerts.push(t); }),
  requestTriage: vi.fn(async () => {}),
};

beforeEach(() => {
  db = new Database(':memory:');
  db.exec(schema);
  runMigrations(db);
  db.pragma('foreign_keys = ON');
  alerts.length = 0;
  setPushSender(sender);
});

afterEach(() => {
  setPushSender(null);
  db.close();
  vi.unstubAllEnvs();
  vi.useRealTimers();
});

it('startOperatorDigest: no-op when neither digest nor triage is enabled', () => {
  vi.stubEnv('OPERATOR_DIGEST_ENABLED', 'false');
  vi.stubEnv('TELEGRAM_PUSH_ENABLED', 'false');
  vi.useFakeTimers();
  startOperatorDigest(db);
  vi.advanceTimersByTime(30 * 60_000);
  expect(alerts).toHaveLength(0);
});

it('startOperatorDigest: arms a 15-min tick that sends the daily digest and is idempotent', () => {
  vi.stubEnv('OPERATOR_DIGEST_ENABLED', 'true');
  vi.stubEnv('OPERATOR_DIGEST_HOUR', '12');
  vi.useFakeTimers();
  vi.setSystemTime(new Date('2026-10-06T12:00:00Z'));

  const spy = vi.spyOn(globalThis, 'setInterval');
  startOperatorDigest(db);
  expect(spy).toHaveBeenCalledTimes(1);
  startOperatorDigest(db);
  expect(spy).toHaveBeenCalledTimes(1);
  spy.mockRestore();

  vi.advanceTimersByTime(15 * 60_000);
  expect(alerts).toHaveLength(1);
  expect(alerts[0]).toContain('Djimitflo daily digest');
  expect(db.prepare("SELECT 1 FROM judgments WHERE judgment = 'needs_you_ranking'").get()).toBeTruthy();
});

import { afterEach, beforeEach, describe, expect, it } from 'vitest';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { worstState, recentDeploys } from '../services/operator-cockpit';
import type { HealthState } from '../services/operator-cockpit';

describe('worstState', () => {
  it('returns NOT_APPLICABLE for an empty list (the reduce seed)', () => {
    expect(worstState([])).toBe('NOT_APPLICABLE');
  });

  it('returns the single state when only one is given', () => {
    expect(worstState(['HEALTHY'])).toBe('HEALTHY');
    expect(worstState(['BREACHED'])).toBe('BREACHED');
  });

  it('picks BREACHED over every other state (most severe)', () => {
    const all: HealthState[] = ['BREACHED', 'UNKNOWN', 'STALE', 'DEGRADED', 'HEALTHY', 'NOT_APPLICABLE'];
    expect(worstState(all)).toBe('BREACHED');
    // order independence
    expect(worstState([...all].reverse())).toBe('BREACHED');
  });

  it('ranks UNKNOWN worse than STALE, DEGRADED, HEALTHY, NOT_APPLICABLE', () => {
    expect(worstState(['HEALTHY', 'UNKNOWN', 'STALE'])).toBe('UNKNOWN');
  });

  it('ranks STALE worse than DEGRADED, HEALTHY, NOT_APPLICABLE', () => {
    expect(worstState(['HEALTHY', 'DEGRADED', 'STALE'])).toBe('STALE');
  });

  it('ranks DEGRADED worse than HEALTHY and NOT_APPLICABLE', () => {
    expect(worstState(['HEALTHY', 'NOT_APPLICABLE', 'DEGRADED'])).toBe('DEGRADED');
  });

  it('ranks HEALTHY worse than NOT_APPLICABLE', () => {
    expect(worstState(['NOT_APPLICABLE', 'HEALTHY'])).toBe('HEALTHY');
  });

  it('keeps the worst state when the worst appears multiple times', () => {
    expect(worstState(['HEALTHY', 'BREACHED', 'HEALTHY', 'BREACHED'])).toBe('BREACHED');
  });
});

describe('recentDeploys', () => {
  let dir: string;
  let logFile: string;

  beforeEach(() => {
    dir = fs.mkdtempSync(path.join(os.tmpdir(), 'cockpit-deploys-'));
    logFile = path.join(dir, 'deploy-log.jsonl');
  });

  afterEach(() => {
    fs.rmSync(dir, { recursive: true, force: true });
  });

  it('returns an empty array when the log file is missing', () => {
    expect(recentDeploys(path.join(dir, 'no-such.jsonl'))).toEqual([]);
  });

  it('parses valid JSONL deploy entries newest first', () => {
    const entries = [
      { at: '2026-10-13T00:00:00.000Z', event: 'deploy', sha: 'aaa', detail: 'first' },
      { at: '2026-10-13T01:00:00.000Z', event: 'deploy', sha: 'bbb', detail: 'second' },
      { at: '2026-10-13T02:00:00.000Z', event: 'rollback', sha: 'bbb', detail: 'rolled back' },
    ];
    fs.writeFileSync(logFile, entries.map((e) => JSON.stringify(e)).join('\n') + '\n');

    const got = recentDeploys(logFile);
    expect(got).toHaveLength(3);
    // newest first (slice(-limit).reverse())
    expect(got[0].sha).toBe('bbb');
    expect(got[1].sha).toBe('bbb');
    expect(got[2].sha).toBe('aaa');
    expect(got.map((d) => d.event)).toEqual(['rollback', 'deploy', 'deploy']);
  });

  it('skips lines that are not valid JSON or lack an event field', () => {
    fs.writeFileSync(
      logFile,
      [
        JSON.stringify({ at: '2026-10-13T00:00:00.000Z', event: 'deploy', sha: 'a', detail: '' }),
        'not json',
        JSON.stringify({ at: '2026-10-13T00:00:00.000Z', sha: 'no-event' }),
        JSON.stringify({ at: '2026-10-13T01:00:00.000Z', event: 'deploy', sha: 'b', detail: '' }),
      ].join('\n') + '\n',
    );

    const got = recentDeploys(logFile);
    expect(got).toHaveLength(2);
    expect(got.map((d) => d.sha)).toEqual(['b', 'a']);
  });

  it('honors the limit argument (last N entries, reversed)', () => {
    const lines: string[] = [];
    for (let i = 0; i < 5; i++) {
      lines.push(JSON.stringify({ at: `2026-10-13T0${i}:00:00.000Z`, event: 'deploy', sha: `s${i}`, detail: '' }));
    }
    fs.writeFileSync(logFile, lines.join('\n') + '\n');

    const got = recentDeploys(logFile, 2);
    expect(got).toHaveLength(2);
    // last 2 entries (s3, s4) reversed => s4, s3
    expect(got.map((d) => d.sha)).toEqual(['s4', 's3']);
  });

  it('returns an empty array for an empty file', () => {
    fs.writeFileSync(logFile, '');
    expect(recentDeploys(logFile)).toEqual([]);
  });
});

import { describe, expect, it } from 'vitest';
import { loadTsParser, reportSummary, type ShippedCodeReport } from '../services/shipped-code-scan';

describe('loadTsParser', () => {
  it('returns null or a parser exposing createSourceFile and forEachChild', () => {
    const ts = loadTsParser();
    if (ts === null) {
      expect(ts).toBeNull();
    } else {
      expect(typeof ts.createSourceFile).toBe('function');
      expect(typeof ts.forEachChild).toBe('function');
      expect(typeof ts.version).toBe('string');
      expect(ts.version.length).toBeGreaterThan(0);
    }
  });

  it('caches the resolved parser (same reference on second call)', () => {
    const first = loadTsParser();
    const second = loadTsParser();
    expect(second).toBe(first);
  });
});

describe('reportSummary', () => {
  function makeReport(over: Partial<ShippedCodeReport> = {}): ShippedCodeReport {
    return {
      schema: 'shipped-code-scan/v1',
      package: { name: 'demo', version: '1.0.0' },
      parser: { name: 'typescript', version: '5.0.0' },
      limits: { max_parse_bytes: 1, max_files: 2, max_hash_bytes: 3 },
      lifecycle: [{ script: 'postinstall', command: 'echo hi' }],
      nested_lifecycle: [{ package: 'dep@2.0.0', path: 'node_modules/dep', script: 'install', command: 'node setup.js' }],
      bin: [{ name: 'demo', path: 'bin/demo.js' }],
      files: [
        { path: 'index.js', size: 10, sha256: 'a'.repeat(64) },
        { path: 'lib.js', size: 20, sha256: 'b'.repeat(64) },
      ],
      symlinks: [{ path: 'link', target: 'target' }],
      binaries: [{ path: 'native.so', format: 'elf', size: 99, sha256: 'c'.repeat(64) }],
      js: { parsed: 1, skipped: [{ path: 'big.js', reason: 'too_large' }] },
      findings: [
        { kind: 'eval', file: 'index.js', line: 3, detail: 'eval(...)' },
        { kind: 'eval', file: 'index.js', line: 7, detail: 'eval(...)' },
        { kind: 'endpoint', file: 'lib.js', line: 1, detail: 'fetch https://x.example.com' },
      ],
      hosts: ['x.example.com'],
      truncated: ['max_files'],
      report_hash: 'd'.repeat(64),
      ...over,
    };
  }

  it('counts files, parsed, skipped, lifecycle, bins, binaries, symlinks, hosts', () => {
    const s = reportSummary(makeReport());
    expect(s.files).toBe(2);
    expect(s.js_parsed).toBe(1);
    expect(s.js_skipped).toBe(1);
    expect(s.lifecycle_scripts).toBe(1);
    expect(s.nested_lifecycle_scripts).toBe(1);
    expect(s.bins).toBe(1);
    expect(s.binaries).toBe(1);
    expect(s.symlinks).toBe(1);
    expect(s.hosts).toBe(1);
  });

  it('groups findings by kind', () => {
    const s = reportSummary(makeReport());
    expect(s.findings_by_kind).toEqual({ eval: 2, endpoint: 1 });
  });

  it('reports the parser version or null when parser is absent', () => {
    expect(reportSummary(makeReport()).parser).toBe('5.0.0');
    expect(reportSummary(makeReport({ parser: null })).parser).toBeNull();
  });

  it('echoes the truncated array verbatim', () => {
    const s = reportSummary(makeReport({ truncated: ['max_files', 'deadline'] }));
    expect(s.truncated).toEqual(['max_files', 'deadline']);
  });

  it('returns empty findings_by_kind when there are no findings', () => {
    const s = reportSummary(makeReport({ findings: [] }));
    expect(s.findings_by_kind).toEqual({});
  });
});

import { describe, expect, it } from 'vitest';
import {
  notFallbackOutcomeSql,
  notFallbackGoalSql,
  notFallbackRunSql,
  FALLBACK_REF,
} from '../services/ollama-outage-fallback';

describe('ollama-outage-fallback exports — SQL fragment generators', () => {
  it('notFallbackOutcomeSql produces a COALESCE…NOT LIKE clause for the given alias', () => {
    const sql = notFallbackOutcomeSql('so');
    expect(sql).toBe(`COALESCE(so.evidence_refs_json, '') NOT LIKE '%"${FALLBACK_REF}"%'`);
    expect(sql).toContain(FALLBACK_REF);
    expect(sql).toContain('evidence_refs_json');
    expect(sql).toContain('NOT LIKE');
  });

  it('notFallbackOutcomeSql works with any alias name', () => {
    const sql = notFallbackOutcomeSql('outcome_alias_42');
    expect(sql).toContain('outcome_alias_42.evidence_refs_json');
  });

  it('notFallbackGoalSql produces a NOT EXISTS subquery scoped to the goal expression', () => {
    const sql = notFallbackGoalSql('g.id');
    expect(sql).toContain('NOT EXISTS');
    expect(sql).toContain('loop_runs fr JOIN worker_leases fl ON fl.loop_run_id = fr.id');
    expect(sql).toContain('fr.goal_id = g.id');
    expect(sql).toContain("json_extract(fl.metadata, '$.runtime_fallback') IS NOT NULL");
  });

  it('notFallbackRunSql produces a NOT EXISTS subquery scoped to the run expression', () => {
    const sql = notFallbackRunSql("'run-abc'");
    expect(sql).toContain('NOT EXISTS');
    expect(sql).toContain('worker_leases fl');
    expect(sql).toContain("fl.loop_run_id = 'run-abc'");
    expect(sql).toContain("json_extract(fl.metadata, '$.runtime_fallback') IS NOT NULL");
  });

  it('all three fragments reference runtime_fallback metadata (the exclusion key)', () => {
    expect(notFallbackOutcomeSql('x')).toContain(FALLBACK_REF);
    expect(notFallbackGoalSql('y')).toContain('$.runtime_fallback');
    expect(notFallbackRunSql('z')).toContain('$.runtime_fallback');
  });
});

import { describe, it, expect } from 'vitest';
import { safeTokenAccounting, computeTokenAccounting, type MakerTokenAccounting } from '../services/maker-token-accounting';

describe('safeTokenAccounting', () => {
  it('returns the accounting produced by compute when it does not throw', () => {
    const expected = computeTokenAccounting({
      runtime: 'opencode',
      stdout: JSON.stringify({ type: 'step_finish', part: { tokens: { input: 10, output: 5, total: 15 } } }),
      leaseMetadata: { model: 'openai/gpt-4o' },
      durationMs: 42,
    });
    const result = safeTokenAccounting(() => expected, 'opencode');
    expect(result).toBe(expected);
  });

  it('catches a thrown Error and returns an unavailable accounting with the error message', () => {
    const result = safeTokenAccounting(() => { throw new Error('boom'); }, 'codex');
    expect(result.measurement_source).toBe('unavailable');
    expect(result.completeness).toBe('none');
    expect(result.reason).toBe('accounting_error: boom');
    expect(result.runtime).toBe('codex');
    expect(result.version).toBe(1);
  });

  it('preserves the runtime string in the fallback even when compute throws', () => {
    const result = safeTokenAccounting(() => { throw new Error('x'); }, 'claude');
    expect(result.runtime).toBe('claude');
  });

  it('sets all token fields and cost fields to null in the fallback', () => {
    const result = safeTokenAccounting(() => { throw new Error('fail'); }, 'opencode');
    for (const f of ['input_tokens', 'output_tokens', 'cache_read_tokens', 'cache_write_tokens', 'reasoning_tokens', 'total_tokens'] as const) {
      expect(result[f]).toBeNull();
    }
    expect(result.estimated_cost_usd).toBeNull();
    expect(result.cost_completeness).toBeNull();
    expect(result.cost_reason).toBe('accounting failed');
    expect(result.price_input_per_mtok).toBeNull();
    expect(result.price_source).toBeNull();
    expect(result.model_id).toBeNull();
    expect(result.model_source).toBeNull();
    expect(result.provider).toBeNull();
    expect(result.duration_ms).toBeNull();
    expect(result.retry_count).toBe(0);
  });

  it('truncates a very long error message to 200 characters (after the prefix)', () => {
    const longMsg = 'x'.repeat(500);
    const result = safeTokenAccounting(() => { throw new Error(longMsg); }, 'opencode');
    expect(result.reason).toBe(`accounting_error: ${'x'.repeat(200)}`);
    expect(result.reason!.length).toBe('accounting_error: '.length + 200);
  });

  it('handles non-Error thrown values by stringifying them', () => {
    const result = safeTokenAccounting(() => { throw 'string error'; }, 'codex');
    expect(result.reason).toBe('accounting_error: string error');
    expect(result.measurement_source).toBe('unavailable');
  });

  it('handles a thrown object without a message property', () => {
    const result = safeTokenAccounting(() => { throw { code: 42 }; }, 'claude');
    expect(result.reason).toBe('accounting_error: [object Object]');
  });

  it('returns whatever compute yields, including a manually constructed accounting', () => {
    const manual: MakerTokenAccounting = {
      version: 1, runtime: 'mock', model_id: null, model_source: null, provider: null,
      input_tokens: 1, output_tokens: 2, cache_read_tokens: null, cache_write_tokens: null,
      reasoning_tokens: null, total_tokens: 3, duration_ms: 10, retry_count: 0,
      estimated_cost_usd: null, cost_completeness: null, cost_reason: null,
      price_input_per_mtok: null, price_output_per_mtok: null, price_cache_read_per_mtok: null,
      price_cache_write_per_mtok: null, price_source: null, price_version: null,
      measurement_source: 'unavailable', completeness: 'none', reason: 'manual',
    };
    expect(safeTokenAccounting(() => manual, 'mock')).toBe(manual);
  });

  it('does not swallow a returned value — only catches throws', () => {
    let called = false;
    const result = safeTokenAccounting(() => { called = true; return computeTokenAccounting({ runtime: 'atomic', stdout: '', leaseMetadata: {}, durationMs: null }); }, 'atomic');
    expect(called).toBe(true);
    expect(result.runtime).toBe('atomic');
  });
});

import { describe, expect, it } from 'vitest';
import {
  abstractFromNote,
  DISCOVERY_RELEVANCE_POLICY,
  discoveryRelevancePaused,
  discoveryRelevanceSources,
  sourceUnitsEnabled,
} from '../services/expert-source-units-service';

describe('sourceUnitsEnabled', () => {
  it('returns true only when FRONTIER_EXPERT_SOURCE_UNITS_ENABLED is "true"', () => {
    expect(sourceUnitsEnabled({ FRONTIER_EXPERT_SOURCE_UNITS_ENABLED: 'true' })).toBe(true);
  });

  it('returns false when the flag is unset', () => {
    expect(sourceUnitsEnabled({})).toBe(false);
  });

  it('returns false when the flag is any other value', () => {
    expect(sourceUnitsEnabled({ FRONTIER_EXPERT_SOURCE_UNITS_ENABLED: 'false' })).toBe(false);
    expect(sourceUnitsEnabled({ FRONTIER_EXPERT_SOURCE_UNITS_ENABLED: '1' })).toBe(false);
  });
});

describe('discoveryRelevanceSources', () => {
  it('returns null when DISCOVERY_RELEVANCE_SOURCES is unset', () => {
    expect(discoveryRelevanceSources({})).toBeNull();
  });

  it('returns null when the list is empty after trimming', () => {
    expect(discoveryRelevanceSources({ DISCOVERY_RELEVANCE_SOURCES: ' , , ' })).toBeNull();
  });

  it('returns a Set of trimmed source names', () => {
    expect(discoveryRelevanceSources({ DISCOVERY_RELEVANCE_SOURCES: 'a, b ,c' })).toEqual(new Set(['a', 'b', 'c']));
  });
});

describe('discoveryRelevancePaused', () => {
  it('returns true when DISCOVERY_RELEVANCE_PAUSED is "true"', () => {
    expect(discoveryRelevancePaused({ DISCOVERY_RELEVANCE_PAUSED: 'true' })).toBe(true);
  });

  it('returns false when unset', () => {
    expect(discoveryRelevancePaused({})).toBe(false);
  });

  it('returns false for any other value', () => {
    expect(discoveryRelevancePaused({ DISCOVERY_RELEVANCE_PAUSED: 'false' })).toBe(false);
  });
});

describe('DISCOVERY_RELEVANCE_POLICY', () => {
  it('is a non-empty string prefixed with discovery_relevance:', () => {
    expect(typeof DISCOVERY_RELEVANCE_POLICY).toBe('string');
    expect(DISCOVERY_RELEVANCE_POLICY.startsWith('discovery_relevance:')).toBe(true);
    expect(DISCOVERY_RELEVANCE_POLICY.length).toBeGreaterThan('discovery_relevance:'.length);
  });
});

describe('abstractFromNote', () => {
  const longProse = 'A'.repeat(200);
  const longerProse = 'B'.repeat(300);

  it('returns the trimmed text for prose of at least 200 characters', () => {
    expect(abstractFromNote(longProse)).toBe(longProse);
    expect(abstractFromNote(longerProse)).toBe(longerProse);
  });

  it('trims surrounding whitespace before length check and in the result', () => {
    const padded = '   ' + longProse + '   ';
    expect(abstractFromNote(padded)).toBe(longProse);
  });

  it('returns null for a note shorter than 200 characters', () => {
    expect(abstractFromNote('short note')).toBeNull();
    expect(abstractFromNote('A'.repeat(199))).toBeNull();
  });

  it('returns null for a note that is exactly 199 chars after trim', () => {
    const note = '  ' + 'x'.repeat(199) + '  ';
    expect(abstractFromNote(note)).toBeNull();
  });

  it('returns null for notes starting with "scout match" (case-insensitive)', () => {
    const scoutNote = 'scout match: agent, coding, ' + 'y'.repeat(200);
    expect(abstractFromNote(scoutNote)).toBeNull();
    expect(abstractFromNote('Scout Match whatever ' + 'y'.repeat(200))).toBeNull();
    expect(abstractFromNote('SCOUT MATCH ' + 'y'.repeat(200))).toBeNull();
  });

  it('returns null for notes starting with "hf daily" (case-insensitive)', () => {
    const hfNote = 'hf daily: model release, ' + 'y'.repeat(200);
    expect(abstractFromNote(hfNote)).toBeNull();
    expect(abstractFromNote('HF Daily ' + 'y'.repeat(200))).toBeNull();
  });

  it('returns null for non-string input', () => {
    expect(abstractFromNote(null)).toBeNull();
    expect(abstractFromNote(undefined)).toBeNull();
    expect(abstractFromNote(42)).toBeNull();
    expect(abstractFromNote({ text: longProse })).toBeNull();
    expect(abstractFromNote(['array', longProse])).toBeNull();
  });

  it('returns null for an empty string', () => {
    expect(abstractFromNote('')).toBeNull();
  });

  it('returns null for a whitespace-only string', () => {
    expect(abstractFromNote('   \n\t  ')).toBeNull();
  });

  it('does not reject prose that merely contains "scout match" later in the text', () => {
    const note = 'This paper discusses scout matching techniques. ' + 'z'.repeat(200);
    expect(abstractFromNote(note)).toBe(note);
  });
});

import { describe, expect, it } from 'vitest';
import Database from 'better-sqlite3';
import type { Database as DB } from 'better-sqlite3';
import { ensurePowerTable, gpuJobs, tokenLedger } from '../services/resource-ledger';

describe('ensurePowerTable', () => {
  it('creates the host_power_samples table on a fresh database', () => {
    const db = new Database(':memory:') as unknown as DB;
    ensurePowerTable(db);
    const tables = db.prepare("SELECT name FROM sqlite_master WHERE type='table' AND name='host_power_samples'").all() as Array<{ name: string }>;
    expect(tables).toHaveLength(1);
    expect(tables[0].name).toBe('host_power_samples');
    db.close();
  });

  it('creates an index on (host, at)', () => {
    const db = new Database(':memory:') as unknown as DB;
    ensurePowerTable(db);
    const indexes = db.prepare("SELECT name FROM sqlite_master WHERE type='index' AND name='idx_host_power_samples'").all() as Array<{ name: string }>;
    expect(indexes).toHaveLength(1);
    db.close();
  });

  it('is idempotent — calling twice does not throw or duplicate', () => {
    const db = new Database(':memory:') as unknown as DB;
    expect(() => { ensurePowerTable(db); ensurePowerTable(db); }).not.toThrow();
    const tables = db.prepare("SELECT name FROM sqlite_master WHERE type='table' AND name='host_power_samples'").all();
    expect(tables).toHaveLength(1);
    db.close();
  });
});

describe('gpuJobs', () => {
  it('returns an empty array when no source tables exist (safeAll never throws)', () => {
    const db = new Database(':memory:') as unknown as DB;
    expect(gpuJobs(db, '2026-01-01T00:00:00.000Z', '2026-01-31T00:00:00.000Z')).toEqual([]);
    db.close();
  });

  it('returns gym jobs from loop_runs with a remote_host in the window', () => {
    const db = new Database(':memory:') as unknown as DB;
    db.exec(`CREATE TABLE loop_runs (loop_name TEXT, status TEXT, metadata TEXT, created_at TEXT, completed_at TEXT, updated_at TEXT)`);
    db.prepare(`INSERT INTO loop_runs VALUES (?, ?, ?, ?, ?, ?)`).run(
      'evolution-gym', 'completed',
      JSON.stringify({ gym: { remote_host: 'host-a', species: 'alpha' } }),
      '2026-01-10T00:00:00.000Z', '2026-01-10T01:00:00.000Z', '2026-01-10T01:00:00.000Z',
    );
    const jobs = gpuJobs(db, '2026-01-01T00:00:00.000Z', '2026-02-01T00:00:00.000Z');
    expect(jobs).toHaveLength(1);
    expect(jobs[0].consumer).toBe('gym:alpha');
    expect(jobs[0].host).toBe('host-a');
    expect(jobs[0].end).toBeGreaterThan(jobs[0].start);
    db.close();
  });

  it('excludes loop_runs outside the time window', () => {
    const db = new Database(':memory:') as unknown as DB;
    db.exec(`CREATE TABLE loop_runs (loop_name TEXT, status TEXT, metadata TEXT, created_at TEXT, completed_at TEXT, updated_at TEXT)`);
    db.prepare(`INSERT INTO loop_runs VALUES (?, ?, ?, ?, ?, ?)`).run(
      'evolution-gym', 'completed',
      JSON.stringify({ gym: { remote_host: 'host-a', species: 'beta' } }),
      '2025-06-10T00:00:00.000Z', '2025-06-10T01:00:00.000Z', '2025-06-10T01:00:00.000Z',
    );
    const jobs = gpuJobs(db, '2026-01-01T00:00:00.000Z', '2026-02-01T00:00:00.000Z');
    expect(jobs).toEqual([]);
    db.close();
  });

  it('returns remote maker jobs and committee jobs in the window', () => {
