  it('noteScheduler coerces truthy non-booleans to a boolean armed flag', () => {
    noteScheduler('c', 'ENABLE_C', 1 as unknown as boolean);
    const found = listSchedulers().schedulers.find((s) => s.name === 'c');
    expect(found?.armed).toBe(true);
  });

  it('markRun records the last tick and surfaces errors as short messages', () => {
    noteScheduler('t', 'ENABLE_T', true, 1000);
    markRun('t');
    expect(schedulerStatus({ name: 't', flag: 'ENABLE_T', armed: true, interval_ms: 1000, last_run: 'x', last_error: null } as SchedulerInfo, 1_000_000)).not.toBe('failing');

    markRun('t', new Error('boom'));
    const info = listSchedulers().schedulers.find((s) => s.name === 't');
    expect(info?.last_error).toBe('boom');
    expect(info?.status).toBe('failing');
  });

  it('markRun truncates long error payloads to 200 chars and never throws', () => {
    noteScheduler('long', 'ENABLE_LONG', true, 1000);
    const big = 'x'.repeat(500);
    expect(() => markRun('long', big)).not.toThrow();
    const info = listSchedulers().schedulers.find((s) => s.name === 'long');
    expect(info?.last_error?.length).toBeLessThanOrEqual(200);
    expect(info?.last_error).toBe(big.slice(0, 200));
  });

  it('schedulerStatus returns off for disarmed schedulers regardless of ticks', () => {
    expect(schedulerStatus({ name: 'd', flag: 'ENABLE_D', armed: false, interval_ms: 1000, last_run: '2000-01-01T00:00:00.000Z', last_error: null } as SchedulerInfo, 1_000_000)).toBe('off');
  });

  it('schedulerStatus returns failing when last_error is set, even if recently ticked', () => {
    expect(
      schedulerStatus(
        { name: 'f', flag: 'ENABLE_F', armed: true, interval_ms: 1000, last_run: '2000-01-01T00:00:00.000Z', last_error: 'bad' } as SchedulerInfo,
        Date.parse('2000-01-01T00:00:00.000Z'),
      ),
    ).toBe('failing');
  });

  it('schedulerStatus returns executing when ticked within 2x interval', () => {
    const now = 10_000;
    expect(
      schedulerStatus({ name: 'e', flag: 'ENABLE_E', armed: true, interval_ms: 1000, last_run: new Date(now - 1000).toISOString(), last_error: null } as SchedulerInfo, now),
    ).toBe('executing');
  });

  it('schedulerStatus returns unknown when armed with no interval and no tick', () => {
    expect(
      schedulerStatus({ name: 'u', flag: 'ENABLE_U', armed: true, interval_ms: null, last_run: null, last_error: null } as SchedulerInfo, 1_000_000),
    ).toBe('unknown');
  });

  it('schedulerStatus returns executing when armed with no interval but a tick is present', () => {
    expect(
      schedulerStatus({ name: 'u2', flag: 'ENABLE_U2', armed: true, interval_ms: null, last_run: '2000-01-01T00:00:00.000Z', last_error: null } as SchedulerInfo, 1_000_000),
    ).toBe('executing');
  });

  it('schedulerStatus returns armed_pending inside the boot grace and armed_not_ticking past it', () => {
    const bootTime = 5_000_000;
    resetSchedulers(bootTime);
    const interval = 1000;
    const window = 2 * interval;
    const pending = schedulerStatus(
      { name: 'p', flag: 'ENABLE_P', armed: true, interval_ms: interval, last_run: null, last_error: null } as SchedulerInfo,
      bootTime + window - 1,
    );
    expect(pending).toBe('armed_pending');
    const notTicking = schedulerStatus(
      { name: 'n', flag: 'ENABLE_N', armed: true, interval_ms: interval, last_run: null, last_error: null } as SchedulerInfo,
      bootTime + window + 1,
    );
    expect(notTicking).toBe('armed_not_ticking');
  });

  it('listSchedulers sorts armed-first then by name and counts by_status', () => {
    noteScheduler('zeta', 'ENABLE_Z', false);
    noteScheduler('alpha', 'ENABLE_A', true, 1000);
    noteScheduler('mid', 'ENABLE_M', true, 1000);
    const result = listSchedulers(1_000_000);
    expect(result.schedulers.map((s) => s.name)).toEqual(['alpha', 'mid', 'zeta']);
    expect(result.armed).toBe(2);
    expect(result.off).toBe(1);
    expect(result.by_status.off).toBe(1);
    const statusKeys: SchedulerStatus[] = ['off', 'executing', 'failing', 'armed_pending', 'armed_not_ticking', 'unknown'];
    for (const k of statusKeys) expect(result.by_status[k]).toBeTypeOf('number');
  });

  it('listSchedulers health is BREACHED when an armed scheduler is failing', () => {
    noteScheduler('bad', 'ENABLE_BAD', true, 1000);
    markRun('bad', new Error('nope'));
    expect(listSchedulers(1_000_000).health).toBe('BREACHED');
  });

  it('listSchedulers health is BREACHED when an armed scheduler stops ticking past grace', () => {
    const bootTime = 1_000_000;
    resetSchedulers(bootTime);
    noteScheduler('stale', 'ENABLE_STALE', true, 1000);
    expect(listSchedulers(bootTime + 10_000).health).toBe('BREACHED');
  });

  it('listSchedulers health is UNKNOWN when an armed scheduler has no interval and no tick', () => {
    noteScheduler('opaque', 'ENABLE_OPAQUE', true, null);
    expect(listSchedulers(1_000_000).health).toBe('UNKNOWN');
  });

  it('listSchedulers health is HEALTHY when all armed schedulers tick within window', () => {
    noteScheduler('ok', 'ENABLE_OK', true, 1000);
    markRun('ok');
    expect(listSchedulers(1_000_000).health).toBe('HEALTHY');
  });

  it('schedulerHealth returns the health and by_status projection of listSchedulers', () => {
    noteScheduler('ok', 'ENABLE_OK', true, 1000);
    markRun('ok');
    noteScheduler('down', 'ENABLE_DOWN', false);
    const health = schedulerHealth(1_000_000);
    expect(health.health).toBe('HEALTHY');
    expect(health.by_status.off).toBe(1);
    expect(health.by_status.executing).toBeGreaterThanOrEqual(1);
  });

  it('resetSchedulers clears the registry and resets boot time', () => {
    noteScheduler('temp', 'ENABLE_TEMP', true, 1000);
    markRun('temp');
    resetSchedulers(2_000_000);
    const result = listSchedulers(2_000_000);
    expect(result.schedulers).toEqual([]);
    expect(result.armed).toBe(0);
  });
});

import { afterEach, describe, expect, it, vi } from 'vitest';
import { scholarlyAbstractFetcher } from '../services/technique-card-service';

afterEach(() => vi.unstubAllGlobals());

const dataciteBody = (doi: string, abstract: string) => ({
  data: {
    attributes: {
      doi,
      titles: [{ title: `Paper ${doi}` }],
      descriptions: [{ description: abstract, descriptionType: 'Abstract' }],
      creators: [],
      subjects: [],
    },
  },
});

const arxivXml = (id: string, summary: string) =>
  `<feed xmlns="http://www.w3.org/2005/Atom"><entry><id>http://arxiv.org/abs/${id}</id><title>Paper ${id}</title><summary>${summary}</summary><author><name>A Researcher</name></author></entry></feed>`;

const isDatacite = (url: string) => url.includes('api.datacite.org');
const isArxiv = (url: string) => url.includes('export.arxiv.org');

describe('scholarlyAbstractFetcher', () => {
  it('returns the DataCite abstract for a doi: ref', async () => {
    vi.stubGlobal(
      'fetch',
      vi.fn(async (input: string | URL | Request) => {
        const url = String(input);
        if (isDatacite(url)) return new Response(JSON.stringify(dataciteBody('10.48550/arxiv.2601.04728', 'DataCite abstract.')), { status: 200 });
        throw new Error(`unexpected ${url}`);
      }) as unknown as typeof fetch,
    );
    const fetcher = scholarlyAbstractFetcher();
    expect(await fetcher('doi:10.48550/arxiv.2601.04728')).toBe('DataCite abstract.');
  });

  it('returns null for a doi: ref DataCite does not hold (no arXiv fallback for DOI refs)', async () => {
    const calls: string[] = [];
    vi.stubGlobal(
      'fetch',
      vi.fn(async (input: string | URL | Request) => {
        const url = String(input);
        calls.push(url);
        if (isDatacite(url)) return new Response('', { status: 404 });
        throw new Error(`unexpected ${url}`);
      }) as unknown as typeof fetch,
    );
    const fetcher = scholarlyAbstractFetcher();
    expect(await fetcher('doi:10.9999/missing')).toBeNull();
    expect(calls.every(isDatacite)).toBe(true);
  });

  it('returns the DataCite abstract for an arxiv: ref without calling arXiv when DataCite has it', async () => {
    const calls: string[] = [];
    vi.stubGlobal(
      'fetch',
      vi.fn(async (input: string | URL | Request) => {
        const url = String(input);
        calls.push(url);
        if (isDatacite(url)) return new Response(JSON.stringify(dataciteBody('10.48550/arxiv.2601.04728', 'From DataCite.')), { status: 200 });
        throw new Error(`unexpected ${url}`);
      }) as unknown as typeof fetch,
    );
    const fetcher = scholarlyAbstractFetcher();
    expect(await fetcher('arxiv:2601.04728')).toBe('From DataCite.');
    expect(calls.every(isDatacite)).toBe(true);
  });

  it('falls back to the arXiv adapter when DataCite has no DOI for the arXiv id', async () => {
    vi.stubGlobal(
      'fetch',
      vi.fn(async (input: string | URL | Request) => {
        const url = String(input);
        if (isDatacite(url)) return new Response('', { status: 404 });
        if (isArxiv(url)) return new Response(arxivXml('2601.99999', 'From arXiv.'), { status: 200 });
        throw new Error(`unexpected ${url}`);
      }) as unknown as typeof fetch,
    );
    const fetcher = scholarlyAbstractFetcher();
    expect(await fetcher('arxiv:2601.99999')).toBe('From arXiv.');
  });

  it('returns null when neither DataCite nor arXiv has the arXiv id', async () => {
    vi.stubGlobal(
      'fetch',
      vi.fn(async (input: string | URL | Request) => {
        const url = String(input);
        if (isDatacite(url)) return new Response('', { status: 404 });
        if (isArxiv(url)) return new Response('<feed xmlns="http://www.w3.org/2005/Atom"></feed>', { status: 200 });
        throw new Error(`unexpected ${url}`);
      }) as unknown as typeof fetch,
    );
    const fetcher = scholarlyAbstractFetcher();
    expect(await fetcher('arxiv:2601.00000')).toBeNull();
  });

  it('returns null for an unrecognized ref without calling any source', async () => {
    const fetchMock = vi.fn();
    vi.stubGlobal('fetch', fetchMock as unknown as typeof fetch);
    const fetcher = scholarlyAbstractFetcher();
    expect(await fetcher('expert:aaaaaaaa-0000-4000-8000-000000000001')).toBeNull();
    expect(fetchMock).not.toHaveBeenCalled();
  });

  it('parses case-insensitive DOI: and ARXIV: prefixes', async () => {
    vi.stubGlobal(
      'fetch',
      vi.fn(async (input: string | URL | Request) => {
        const url = String(input);
        if (isDatacite(url)) return new Response(JSON.stringify(dataciteBody('10.48550/arxiv.2601.04728', 'Lowercase prefix abstract.')), { status: 200 });
        throw new Error(`unexpected ${url}`);
      }) as unknown as typeof fetch,
    );
    const fetcher = scholarlyAbstractFetcher();
    expect(await fetcher('DOI:10.48550/arxiv.2601.04728')).toBe('Lowercase prefix abstract.');
    expect(await fetcher('ARXIV:2601.04728')).toBe('Lowercase prefix abstract.');
  });

  it('returns null for a malformed arXiv id (wrong digit shape)', async () => {
    const fetchMock = vi.fn();
    vi.stubGlobal('fetch', fetchMock as unknown as typeof fetch);
    const fetcher = scholarlyAbstractFetcher();
    expect(await fetcher('arxiv:not-an-id')).toBeNull();
    expect(fetchMock).not.toHaveBeenCalled();
  });
});

import { afterEach, beforeEach, describe, expect, it } from 'vitest';
import { createHmac } from 'crypto';
import Database from 'better-sqlite3';
import {
  ensureFleetSignatureTables,
  deriveFleetHmacKey,
  recordFleetVerdict,
} from '../services/fleet-event-signatures';
import type { FleetVerification, FleetSignatureMode } from '../services/fleet-event-signatures';

let db: Database.Database;
beforeEach(() => {
  db = new Database(':memory:');
});
afterEach(() => {
  db.close();
});

describe('ensureFleetSignatureTables', () => {
  it('creates the three expected tables', () => {
    ensureFleetSignatureTables(db);
    const tables = db.prepare("SELECT name FROM sqlite_master WHERE type='table' AND name IN ('fleet_event_keys','fleet_event_nonces','fleet_event_signatures') ORDER BY name").all() as Array<{ name: string }>;
    expect(tables.map((r) => r.name)).toEqual(['fleet_event_keys', 'fleet_event_nonces', 'fleet_event_signatures']);
  });

  it('is idempotent (calling twice does not throw)', () => {
    ensureFleetSignatureTables(db);
    expect(() => ensureFleetSignatureTables(db)).not.toThrow();
  });

  it('creates the nonce index', () => {
    ensureFleetSignatureTables(db);
    const idx = db.prepare("SELECT name FROM sqlite_master WHERE type='index' AND name='idx_fleet_event_nonces_seen'").get();
    expect(idx).toBeDefined();
  });
});

describe('deriveFleetHmacKey', () => {
  it('returns a base64url-encoded HMAC-SHA256 digest', () => {
    const key = deriveFleetHmacKey('master-secret', 'host1', 'abcdef01');
    // base64url alphabet only
    expect(key).toMatch(/^[A-Za-z0-9_-]+$/);
    // length of sha256 in base64url is 43 chars
    expect(key.length).toBe(43);
  });

  it('matches an independently computed HMAC', () => {
    const master = 'my-master';
    const host = 'node.example.com';
    const keyId = 'deadbeefcafe0001';
    const expected = createHmac('sha256', master)
      .update(`fleet-event-key|v1|${host}|${keyId}`)
      .digest('base64url');
    expect(deriveFleetHmacKey(master, host, keyId)).toBe(expected);
  });

  it('produces different keys for different hosts', () => {
    const a = deriveFleetHmacKey('m', 'host-a', 'k1');
    const b = deriveFleetHmacKey('m', 'host-b', 'k1');
    expect(a).not.toBe(b);
  });

  it('produces different keys for different keyIds', () => {
    const a = deriveFleetHmacKey('m', 'h', 'aaaa0001');
    const b = deriveFleetHmacKey('m', 'h', 'bbbb0002');
    expect(a).not.toBe(b);
  });

  it('is deterministic (same inputs → same output)', () => {
    expect(deriveFleetHmacKey('x', 'y', 'z')).toBe(deriveFleetHmacKey('x', 'y', 'z'));
  });
});

describe('recordFleetVerdict', () => {
  const v: FleetVerification = { verdict: 'verified', host: 'h1', key_id: 'abcd1234' };
  const mode: FleetSignatureMode = 'shadow';
  const now = Date.parse('2025-06-01T00:00:00Z');

  it('inserts a row into fleet_event_signatures', () => {
    ensureFleetSignatureTables(db);
    recordFleetVerdict(db, 'evt-1', v, mode, now);
    const row = db.prepare('SELECT * FROM fleet_event_signatures WHERE event_id = ?').get('evt-1') as Record<string, unknown> | undefined;
    expect(row).toBeDefined();
    expect(row!.host).toBe('h1');
    expect(row!.key_id).toBe('abcd1234');
    expect(row!.verdict).toBe('verified');
    expect(row!.mode).toBe('shadow');
    expect(row!.at).toBe(new Date(now).toISOString());
  });

  it('ignores duplicate event_ids (INSERT OR IGNORE)', () => {
    ensureFleetSignatureTables(db);
    recordFleetVerdict(db, 'evt-dup', v, mode, now);
    // second insert with same event_id but different verdict should be ignored
    recordFleetVerdict(db, 'evt-dup', { ...v, verdict: 'replay' }, 'enforce', now + 1000);
    const rows = db.prepare('SELECT * FROM fleet_event_signatures WHERE event_id = ?').all('evt-dup') as Array<Record<string, unknown>>;
    expect(rows.length).toBe(1);
    expect(rows[0].verdict).toBe('verified');
  });

  it('stores null host and key_id when verification has no host/key', () => {
    ensureFleetSignatureTables(db);
    const unsigned: FleetVerification = { verdict: 'unsigned', host: null, key_id: null };
    recordFleetVerdict(db, 'evt-ns', unsigned, 'off', now);
    const row = db.prepare('SELECT * FROM fleet_event_signatures WHERE event_id = ?').get('evt-ns') as Record<string, unknown> | undefined;
    expect(row!.host).toBeNull();
    expect(row!.key_id).toBeNull();
    expect(row!.verdict).toBe('unsigned');
  });
});

import { afterEach, beforeEach, describe, expect, it } from 'vitest';
import type Database from 'better-sqlite3';
import { experimentArms, recordMakerCall, ledgerTotals } from '../services/model-call-ledger';
import { createTestDb } from './helpers/test-db';

describe('model-call-ledger exports (experimentArms, recordMakerCall, ledgerTotals)', () => {
  let db: Database.Database;

  beforeEach(() => {
    db = createTestDb();
    // The shared test-db helper does not create llm_model_calls (added by runMigrations);
    // create the minimum shape recordModelCall / ledgerTotals read/write.
    db.exec(`
      CREATE TABLE IF NOT EXISTS llm_model_calls (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        consumer TEXT NOT NULL,
        model TEXT NOT NULL,
        ok INTEGER NOT NULL,
        latency_ms INTEGER,
        out_chars INTEGER,
        shadow INTEGER NOT NULL DEFAULT 0,
        agree INTEGER,
        provider TEXT,
        tokens_in INTEGER,
        tokens_out INTEGER,
        task_kind TEXT,
        run_id TEXT,
        status TEXT,
        attempts INTEGER,
        purpose TEXT,
        experiment_id TEXT,
        cost_basis TEXT,
        list_price_cost REAL,
        marginal_cost REAL,
        created_at TEXT NOT NULL
      );
    `);
  });

  afterEach(() => {
    db.close();
  });

  describe('experimentArms', () => {
    it('returns null when no arms are present', () => {
      expect(experimentArms(db, null, null, null)).toBeNull();
    });

    it('formats the ACE arm as ACE-001:<arm>', () => {
      expect(experimentArms(db, null, { arm: '01' }, null)).toBe('ACE-001:01');
    });

    it('formats the STE arm as STE-001:<arm>', () => {
      expect(experimentArms(db, null, null, { arm: 1 })).toBe('STE-001:1');
    });

    it('joins ACE and STE arms in order', () => {
      expect(experimentArms(db, null, { arm: 'cross' }, { arm: 2 })).toBe('ACE-001:cross,STE-001:2');
    });

    it('appends the F2 arm from the goal metadata checker_family_arm', () => {
      db.prepare("INSERT INTO goals (id, objective, metadata) VALUES ('g1', 'o', ?)").run(
        JSON.stringify({ checker_family_arm: 'cross' }),
      );
      expect(experimentArms(db, 'g1', { arm: '01' }, { arm: 1 })).toBe('ACE-001:01,STE-001:1,F2:cross');
    });

    it('omits the F2 arm when the goal has no checker_family_arm metadata', () => {
      db.prepare("INSERT INTO goals (id, objective, metadata) VALUES ('g2', 'o', '{}')").run();
      expect(experimentArms(db, 'g2', null, null)).toBeNull();
    });

    it('returns null when the goal id does not exist (query yields nothing)', () => {
      expect(experimentArms(db, 'missing', null, null)).toBeNull();
    });

    it('still returns ACE/STE arms when the goals table lookup throws (old schema)', () => {
      db.exec('DROP TABLE goals');
      expect(experimentArms(db, 'gone', { arm: '01' }, { arm: 1 })).toBe('ACE-001:01,STE-001:1');
    });
  });

  describe('recordMakerCall', () => {
    it('records one row tagged maker:<loopName> with the experiment arms', () => {
      db.prepare("INSERT INTO goals (id, objective, metadata) VALUES ('g9', 'o', ?)").run(
        JSON.stringify({ checker_family_arm: 'cross' }),
      );
      recordMakerCall(db, {
        runId: 'run-1',
        goalId: 'g9',
        loopName: 'self-improvement',
        runtime: 'opencode',
        meta: { model: 'glm-5.2', runtime_usage: { input_tokens: 1200, output_tokens: 300 } },
        ace: { arm: '01' },
        ste: { arm: 1 },
        durationMs: 42,
        ok: true,
      });
      const row = db.prepare('SELECT consumer, model, provider, task_kind, run_id, purpose, experiment_id, status, tokens_in, tokens_out FROM llm_model_calls').get() as Record<string, unknown>;
      expect(row.consumer).toBe('maker');
      expect(row.model).toBe('glm-5.2');
      expect(row.provider).toBe('opencode');
      expect(row.task_kind).toBe('self-improvement');
      expect(row.run_id).toBe('run-1');
      expect(row.purpose).toBe('maker:self-improvement');
      expect(row.experiment_id).toBe('ACE-001:01,STE-001:1,F2:cross');
      expect(row.status).toBe('verified');
      expect(row.tokens_in).toBe(1200);
      expect(row.tokens_out).toBe(300);
    });

    it('falls back to the runtime as the model when meta.model is absent', () => {
      recordMakerCall(db, {
        runId: 'run-2', goalId: null, loopName: 'planning', runtime: 'codex',
        meta: { runtime_usage: { total_tokens: 500 } }, ace: null, ste: null, durationMs: 7, ok: false,
      });
      const row = db.prepare('SELECT model, provider, status, tokens_in, tokens_out, experiment_id FROM llm_model_calls').get() as Record<string, unknown>;
      expect(row.model).toBe('codex');
      expect(row.provider).toBe('codex');
      expect(row.status).toBe('not_verified');
      expect(row.tokens_in).toBe(500);
      expect(row.tokens_out).toBeNull();
      expect(row.experiment_id).toBeNull();
    });

    it('never throws when the llm_model_calls table is missing (ledger must not break the call)', () => {
      db.exec('DROP TABLE llm_model_calls');
      expect(() =>
        recordMakerCall(db, {
          runId: 'run-3', goalId: null, loopName: 'x', runtime: 'opencode',
          meta: { runtime_usage: {} }, ace: null, ste: null, durationMs: 1, ok: true,
        }),
      ).not.toThrow();
    });
  });

  describe('ledgerTotals', () => {
    it('groups by purpose and experiment_id over the since cutoff', () => {
      const now = new Date().toISOString();
      db.prepare(`INSERT INTO llm_model_calls (consumer, model, ok, latency_ms, out_chars, shadow, tokens_in, tokens_out, purpose, experiment_id, cost_basis, list_price_cost, marginal_cost, created_at)
        VALUES ('maker','m',1,10,0,0,100,20,'maker:self-improvement','ACE-001:01','metered',0.01,0.01,?),
               ('maker','m',0,5,0,0,NULL,NULL,'maker:self-improvement','ACE-001:01','unknown',NULL,NULL,?),
               ('maker','m',1,8,0,0,50,10,'maker:planning',NULL,'local',NULL,0,?)`).run(now, now, now);
      const totals = ledgerTotals(db, '2000-01-01T00:00:00.000Z');
      expect(totals.by_purpose).toHaveLength(2);
      const si = totals.by_purpose.find((r) => r.key === 'maker:self-improvement') as Record<string, unknown>;
      expect(si.calls).toBe(2);
      expect(si.ok).toBe(1);
      expect(si.calls_tokens_unknown).toBe(1);
      expect(si.tokens_in).toBe(100);
      expect(si.tokens_out).toBe(20);
      const plan = totals.by_purpose.find((r) => r.key === 'maker:planning') as Record<string, unknown>;
      expect(plan.calls).toBe(1);
      expect(totals.by_experiment).toHaveLength(1);
      const ace = totals.by_experiment[0] as Record<string, unknown>;
      expect(ace.key).toBe('ACE-001:01');
      expect(ace.calls).toBe(2);
    });

    it('returns empty arrays when no rows match the window', () => {
      const totals = ledgerTotals(db, '9999-12-31T00:00:00.000Z');
      expect(totals.by_purpose).toEqual([]);
      expect(totals.by_experiment).toEqual([]);
    });

    it('returns empty arrays when the llm_model_calls table is missing', () => {
      db.exec('DROP TABLE llm_model_calls');
      const totals = ledgerTotals(db, '2000-01-01T00:00:00.000Z');
      expect(totals.by_purpose).toEqual([]);
      expect(totals.by_experiment).toEqual([]);
    });
  });
});

