import { describe, expect, it } from 'vitest';
import Database from 'better-sqlite3';
import {
  FALLBACK_REF,
  notFallbackGoalSql,
  notFallbackOutcomeSql,
  notFallbackRunSql,
} from '../services/ollama-outage-fallback';

const makeDb = () => {
  const db = new Database(':memory:');
  db.exec(`CREATE TABLE loop_runs (
    id TEXT PRIMARY KEY,
    goal_id TEXT NOT NULL
  )`);
  db.exec(`CREATE TABLE worker_leases (
    id TEXT PRIMARY KEY,
    loop_run_id TEXT NOT NULL,
    metadata TEXT NOT NULL
  )`);
  db.exec(`CREATE TABLE outcomes (
    id TEXT PRIMARY KEY,
    evidence_refs_json TEXT
  )`);
  return db;
};

const fallbackMeta = () => JSON.stringify({ runtime_fallback: { from: 'opencode', to: 'claude' } });
const plainMeta = () => JSON.stringify({});

describe('ollama-outage-fallback exports — notFallbackOutcomeSql', () => {
  it('emits a SQL fragment that excludes outcomes whose evidence_refs_json contains the fallback ref', () => {
    const db = makeDb();
    const sql = notFallbackOutcomeSql('o');
    expect(sql).toContain('COALESCE(o.evidence_refs_json,');
    expect(sql).toContain(FALLBACK_REF);

    db.prepare(`INSERT INTO outcomes (id, evidence_refs_json) VALUES (?, ?), (?, ?), (?, ?)`).run(
      'out-plain',
      JSON.stringify(['other:ref']),
      'out-fallback',
      JSON.stringify([FALLBACK_REF, 'other:ref']),
      'out-null',
      null,
    );

    const rows = db
      .prepare(`SELECT o.id AS id FROM outcomes o WHERE ${sql} ORDER BY o.id`)
      .all() as { id: string }[];
    // plain and null (COALESCE → '') pass; the fallback outcome is excluded
    expect(rows.map((r) => r.id)).toEqual(['out-null', 'out-plain']);
  });
});

describe('ollama-outage-fallback exports — notFallbackGoalSql', () => {
  it('emits a SQL fragment that is true only for goals with no fallback lease', () => {
    const db = makeDb();
    const sql = notFallbackGoalSql('g.goal_id');
    expect(sql).toContain('loop_runs fr');
    expect(sql).toContain('json_extract(fl.metadata');
    expect(sql).toContain('g.goal_id');

    db.prepare(`INSERT INTO loop_runs (id, goal_id) VALUES (?, ?), (?, ?), (?, ?)`).run(
      'run-clean',
      'goal-clean',
      'run-fallback',
      'goal-fallback',
      'run-mixed',
      'goal-mixed',
    );
    db.prepare(`INSERT INTO worker_leases (id, loop_run_id, metadata) VALUES (?, ?, ?), (?, ?, ?), (?, ?, ?)`).run(
      'lease-clean',
      'run-clean',
      plainMeta(),
      'lease-fallback',
      'run-fallback',
      fallbackMeta(),
      'lease-mixed-plain',
      'run-mixed',
      plainMeta(),
    );
    db.prepare(`INSERT INTO worker_leases (id, loop_run_id, metadata) VALUES (?, ?, ?)`).run(
      'lease-mixed-fallback',
      'run-mixed',
      fallbackMeta(),
    );

    const goals = db
      .prepare(
        `SELECT g.goal_id AS goal_id, CASE WHEN ${sql} THEN 1 ELSE 0 END AS ok FROM (SELECT 'goal-clean' AS goal_id UNION ALL SELECT 'goal-fallback' UNION ALL SELECT 'goal-mixed') g ORDER BY g.goal_id`,
      )
      .all() as { goal_id: string; ok: number }[];
    const byGoal = new Map(goals.map((g) => [g.goal_id, g.ok]));
    expect(byGoal.get('goal-clean')).toBe(1);
    expect(byGoal.get('goal-fallback')).toBe(0);
    expect(byGoal.get('goal-mixed')).toBe(0);
  });
});

describe('ollama-outage-fallback exports — notFallbackRunSql', () => {
  it('emits a SQL fragment that is true only for runs with no fallback lease', () => {
    const db = makeDb();
    const sql = notFallbackRunSql('r.id');
