    expect(s).toBe('sha <id> caused the failure');
  });

  it('does not replace a short all-digit token as a hex id', () => {
    // "12345" is only 5 chars and has no letter — stays as a number → <n>
    const s = templateSkeleton('run 12345 done');
    expect(s).toBe('run <n> done');
  });

  it('replaces integers with <n>', () => {
    const s = templateSkeleton('score was 97 out of 100');
    expect(s).toBe('score was <n> out of <n>');
  });

  it('replaces decimals with <n>', () => {
    const s = templateSkeleton('confidence 0.85 recorded');
    expect(s).toBe('confidence <n> recorded');
  });

  it('replaces percentages with <n>', () => {
    const s = templateSkeleton('improved by 12% this week');
    expect(s).toBe('improved by <n> this week');
  });

  it('replaces negative numbers with <n>', () => {
    const s = templateSkeleton('delta -3 points');
    expect(s).toBe('delta <n> points');
  });

  it('collapses whitespace and trims', () => {
    const s = templateSkeleton('  hello   world  \n\t foo  ');
    expect(s).toBe('hello world foo');
  });

  it('returns empty string for empty input', () => {
    expect(templateSkeleton('')).toBe('');
  });

  it('leaves plain text without variables unchanged (modulo trim/collapse)', () => {
    expect(templateSkeleton('always use pnpm for installs')).toBe('always use pnpm for installs');
  });

  it('handles combined content: uuid + date + number', () => {
    const s = templateSkeleton(
      'Run aaaa1111-bbbb-cccc-dddd-eeeeffff0000 on 2026-01-02 scored 42',
    );
    expect(s).toBe('Run <id> on <date> scored <n>');
  });
});

describe('recordTemplateDedupError', () => {
  function makeDb(shouldThrow = false) {
    return {
      prepare: vi.fn().mockReturnValue({
        run: vi.fn(() => { if (shouldThrow) throw new Error('no table'); }),
      }),
    };
  }

  it('does not throw when the judgments insert succeeds', () => {
    const db = makeDb(false);
    expect(() => recordTemplateDedupError(db as any, {
      mode: 'shadow', stage: 'lookup', error: new Error('boom'), sourceRef: null,
    })).not.toThrow();
  });

  it('does not throw when the judgments table is absent (insert throws)', () => {
    const db = makeDb(true);
    expect(() => recordTemplateDedupError(db as any, {
      mode: 'enforce', stage: 'record', error: new Error('missing table'), sourceRef: 'loop:abc123',
    })).not.toThrow();
  });

  it('logs a warning containing the stage and mode', () => {
    const warn = vi.spyOn(console, 'warn').mockImplementation(() => {});
    try {
      recordTemplateDedupError(makeDb() as any, {
        mode: 'shadow', stage: 'enforce', error: new Error('db down'), sourceRef: null,
      });
      expect(warn).toHaveBeenCalledTimes(1);
      expect(warn.mock.calls[0][0]).toContain('enforce');
      expect(warn.mock.calls[0][0]).toContain('shadow');
    } finally { warn.mockRestore(); }
  });

  it('stringifies non-Error values for the log message', () => {
    const warn = vi.spyOn(console, 'warn').mockImplementation(() => {});
    try {
      recordTemplateDedupError(makeDb() as any, {
        mode: 'off', stage: 'lookup', error: 'raw string failure', sourceRef: null,
      });
      expect(warn.mock.calls[0][0]).toContain('raw string failure');
    } finally { warn.mockRestore(); }
  });

  it('uses "pending" when subjectId is omitted', () => {
    const db = makeDb(false) as any;
    recordTemplateDedupError(db, {
      mode: 'shadow', stage: 'record', error: new Error('x'), sourceRef: null,
    });
    // The run call receives 'pending' as the subject_id (2nd arg after id)
    const runArgs = db.prepare().run.mock.calls[0];
    expect(runArgs[1]).toBe('pending');
  });

  it('passes through an explicit subjectId', () => {
    const db = makeDb(false) as any;
    recordTemplateDedupError(db, {
      mode: 'enforce', stage: 'lookup', error: new Error('y'), subjectId: 'cand-42', sourceRef: null,
    });
    const runArgs = db.prepare().run.mock.calls[0];
    expect(runArgs[1]).toBe('cand-42');
  });
});

import { afterEach, beforeEach, describe, expect, it } from 'vitest';
import Database from 'better-sqlite3';
import { createHmac } from 'crypto';
import {
  ensureFleetSignatureTables,
  deriveFleetHmacKey,
  recordFleetVerdict,
  type FleetVerification,
} from '../services/fleet-event-signatures';

let db: Database.Database;

beforeEach(() => {
  db = new Database(':memory:');
});

afterEach(() => {
  db.close();
});

describe('ensureFleetSignatureTables', () => {
  it('creates the fleet_event_keys, fleet_event_nonces and fleet_event_signatures tables', () => {
    ensureFleetSignatureTables(db);
    const tables = db.prepare(
      "SELECT name FROM sqlite_master WHERE type = 'table' AND name IN ('fleet_event_keys', 'fleet_event_nonces', 'fleet_event_signatures') ORDER BY name",
    ).all() as Array<{ name: string }>;
    expect(tables.map((t) => t.name)).toEqual([
      'fleet_event_keys',
      'fleet_event_nonces',
      'fleet_event_signatures',
    ]);
  });

  it('creates the idx_fleet_event_nonces_seen index on fleet_event_nonces(seen_at)', () => {
    ensureFleetSignatureTables(db);
    const idx = db.prepare(
      "SELECT name FROM sqlite_master WHERE type = 'index' AND name = 'idx_fleet_event_nonces_seen'",
    ).get() as { name: string } | undefined;
    expect(idx?.name).toBe('idx_fleet_event_nonces_seen');
  });

  it('is idempotent: calling twice does not throw and keeps a single copy of each table', () => {
    expect(() => {
      ensureFleetSignatureTables(db);
      ensureFleetSignatureTables(db);
    }).not.toThrow();
    const tables = db.prepare(
      "SELECT name FROM sqlite_master WHERE type = 'table' AND name = 'fleet_event_signatures'",
    ).all();
    expect(tables).toHaveLength(1);
  });

  it('makes fleet_event_signatures key on event_id so duplicate inserts are ignored', () => {
    ensureFleetSignatureTables(db);
    const info = db.prepare('PRAGMA table_info(fleet_event_signatures)').all() as Array<{ name: string; pk: number }>;
    const eventId = info.find((c) => c.name === 'event_id');
    expect(eventId?.pk).toBeGreaterThan(0);
  });
});

describe('deriveFleetHmacKey', () => {
  it('returns a base64url string derived from HMAC-SHA256(master, "fleet-event-key|v1|<host>|<keyId>")', () => {
    const master = 'test-master-secret';
    const host = 'host-1';
    const keyId = 'deadbeef';
    const expected = createHmac('sha256', master).update(`fleet-event-key|v1|${host}|${keyId}`).digest('base64url');
    expect(deriveFleetHmacKey(master, host, keyId)).toBe(expected);
  });

  it('produces different keys for different hosts or key ids', () => {
    const master = 'm';
    const a = deriveFleetHmacKey(master, 'host-a', 'aaaaaaaa');
    const b = deriveFleetHmacKey(master, 'host-b', 'aaaaaaaa');
    const c = deriveFleetHmacKey(master, 'host-a', 'bbbbbbbb');
    expect(a).not.toBe(b);
    expect(a).not.toBe(c);
    expect(b).not.toBe(c);
  });

  it('is deterministic: the same inputs always yield the same key', () => {
    const k1 = deriveFleetHmacKey('m', 'h', '1234abcd');
    const k2 = deriveFleetHmacKey('m', 'h', '1234abcd');
    expect(k1).toBe(k2);
  });

  it('changes when the master secret changes (rotating the master invalidates fleet keys)', () => {
    const a = deriveFleetHmacKey('master-1', 'h', '1234abcd');
    const b = deriveFleetHmacKey('master-2', 'h', '1234abcd');
    expect(a).not.toBe(b);
  });
});

describe('recordFleetVerdict', () => {
  const verdict = (over: Partial<FleetVerification> = {}): FleetVerification => ({
    verdict: 'verified', host: 'host-1', key_id: 'deadbeef', ...over,
  });

  it('inserts a row into fleet_event_signatures with the given fields and an ISO timestamp', () => {
    ensureFleetSignatureTables(db);
    const now = Date.parse('2024-06-01T00:00:00Z');
    recordFleetVerdict(db, 'evt-1', verdict(), 'shadow', now);
    const row = db.prepare('SELECT * FROM fleet_event_signatures WHERE event_id = ?').get('evt-1') as {
      event_id: string; host: string; key_id: string; verdict: string; mode: string; at: string;
    };
    expect(row).toEqual({
      event_id: 'evt-1',
      host: 'host-1',
      key_id: 'deadbeef',
      verdict: 'verified',
      mode: 'shadow',
      at: new Date(now).toISOString(),
    });
  });

  it('persists null host and key_id (e.g. unsigned / unknown_host verdicts)', () => {
    ensureFleetSignatureTables(db);
    recordFleetVerdict(db, 'evt-2', verdict({ verdict: 'unsigned', host: null, key_id: null }), 'off');
    const row = db.prepare('SELECT host, key_id, verdict, mode FROM fleet_event_signatures WHERE event_id = ?').get('evt-2') as {
      host: string | null; key_id: string | null; verdict: string; mode: string;
    };
    expect(row).toEqual({ host: null, key_id: null, verdict: 'unsigned', mode: 'off' });
  });

  it('uses INSERT OR IGNORE so a second write for the same event_id does not overwrite the first verdict', () => {
    ensureFleetSignatureTables(db);
    const now = Date.parse('2024-06-01T00:00:00Z');
    recordFleetVerdict(db, 'evt-3', verdict({ verdict: 'verified' }), 'shadow', now);
    recordFleetVerdict(db, 'evt-3', verdict({ verdict: 'bad_signature' }), 'enforce', now + 1000);
    const rows = db.prepare('SELECT verdict, mode FROM fleet_event_signatures WHERE event_id = ?').all('evt-3') as Array<{
      verdict: string; mode: string;
    }>;
    expect(rows).toEqual([{ verdict: 'verified', mode: 'shadow' }]);
  });

  it('stores distinct rows for distinct event ids', () => {
    ensureFleetSignatureTables(db);
    recordFleetVerdict(db, 'a', verdict({ verdict: 'verified' }), 'shadow');
    recordFleetVerdict(db, 'b', verdict({ verdict: 'replay', host: 'host-2', key_id: 'cafef00d' }), 'enforce');
    const rows = db.prepare('SELECT event_id, verdict, host FROM fleet_event_signatures ORDER BY event_id').all() as Array<{
      event_id: string; verdict: string; host: string | null;
    }>;
    expect(rows).toEqual([
      { event_id: 'a', verdict: 'verified', host: 'host-1' },
      { event_id: 'b', verdict: 'replay', host: 'host-2' },
    ]);
  });

  it('requires the fleet_event_signatures table to exist (throws otherwise)', () => {
    expect(() => recordFleetVerdict(db, 'evt-x', verdict(), 'shadow')).toThrow();
  });
});

