import { describe, expect, it } from 'vitest';
import { caseOutcome, D5NO_DEADLINE_DAYS, D5NO_MAX_RISK } from '../services/d5-no';

describe('d5-no exports (caseOutcome, D5NO_MAX_RISK, D5NO_DEADLINE_DAYS)', () => {
  it('exposes the frozen protocol risk threshold and deadline window', () => {
    expect(D5NO_MAX_RISK).toBe(0.05);
    expect(D5NO_DEADLINE_DAYS).toBe(90);
  });

  it('classifies a verified status as a false rejection (conservative: any verified wins)', () => {
    expect(caseOutcome(['verified'])).toBe('false_rejection');
    expect(caseOutcome(['regressed', 'verified'])).toBe('false_rejection');
    expect(caseOutcome(['verified', 'proposed'])).toBe('false_rejection');
  });

  it('classifies in-flight statuses as pending (before settling on censored/correct)', () => {
    for (const s of ['proposed', 'scheduled', 'executing', 'evaluating', 'applied']) {
      expect(caseOutcome([s])).toBe('pending');
    }
    expect(caseOutcome(['regressed', 'scheduled'])).toBe('pending');
  });

  it('classifies an all-infra-failed cluster as censored', () => {
    expect(caseOutcome(['infra_failed'])).toBe('censored');
    expect(caseOutcome(['infra_failed', 'infra_failed'])).toBe('censored');
  });

  it('does not call a mixed infra/real-outcome cluster censored (infra_failed is not exhaustive)', () => {
    expect(caseOutcome(['infra_failed', 'regressed'])).toBe('correct_rejection');
    expect(caseOutcome(['infra_failed', 'no_change'])).toBe('correct_rejection');
  });

  it('classifies settled rejection outcomes as correct rejection', () => {
    for (const s of ['rejected', 'no_change', 'regressed', 'needs_more_evidence', 'needs_grounding', 'archived']) {
      expect(caseOutcome([s])).toBe('correct_rejection');
    }
    expect(caseOutcome(['rejected', 'no_change', 'needs_grounding'])).toBe('correct_rejection');
  });

  it('treats an empty status list as a correct rejection (no pending, no infra, no verified)', () => {
    expect(caseOutcome([])).toBe('correct_rejection');
  });

  it('prefers false rejection over pending when both appear (verified short-circuits)', () => {
    expect(caseOutcome(['proposed', 'verified'])).toBe('false_rejection');
  });
});

import { describe, expect, it } from 'vitest';
import {
  DREAM_EXPOSURE_WINDOW_MS,
  DEFAULT_HOLDOUT_SIZE,
  HOLDOUT_SIZE_MAX,
  HOLDOUT_SIZE_MIN,
  exclusionReason,
  resolveHoldoutSize,
} from '../services/holdout-exposure';
import type { HoldoutExclusions } from '../services/holdout-exposure';

const empty = (): HoldoutExclusions => ({
  frozen: new Set(), tg: new Set(), trialAttempted: new Set(),
  exposedCommits: new Set(), exposedSources: new Set(), exposedRuns: new Set(), dreamGenomes: 0,
});

describe('holdout-exposure exports (exclusionReason, resolveHoldoutSize, constants)', () => {
  it('exposes the frozen exposure window and size bounds', () => {
    expect(DREAM_EXPOSURE_WINDOW_MS).toBe(86_400_000);
    expect(DEFAULT_HOLDOUT_SIZE).toBe(20);
    expect(HOLDOUT_SIZE_MIN).toBe(10);
    expect(HOLDOUT_SIZE_MAX).toBe(200);
  });

  describe('exclusionReason', () => {
    it('returns null when nothing matches', () => {
      const ex = empty();
      expect(exclusionReason(ex, { commit: 'abc123' })).toBeNull();
    });

    it('flags a commit already frozen in a holdout epoch', () => {
      const ex = empty(); ex.frozen.add('frozen1');
      expect(exclusionReason(ex, { commit: 'frozen1' })).toBe('already frozen in a holdout epoch');
    });

    it('flags a TG-001 task key', () => {
      const ex = empty(); ex.tg.add('tgkey');
      expect(exclusionReason(ex, { commit: 'tgkey' })).toBe('TG-001 task key');
    });

    it('flags a commit attempted in a genome trial', () => {
      const ex = empty(); ex.trialAttempted.add('trial1');
      expect(exclusionReason(ex, { commit: 'trial1' })).toBe('attempted in a genome trial');
    });

    it('flags a dream-exposed commit', () => {
      const ex = empty(); ex.exposedCommits.add('dexp');
      expect(exclusionReason(ex, { commit: 'dexp' })).toBe('dream-exposed commit');
    });

    it('flags a dream-exposed source file via source field', () => {
      const ex = empty(); ex.exposedSources.add('src/a.ts');
      expect(exclusionReason(ex, { commit: 'x', source: 'src/a.ts' })).toBe('dream-exposed source file src/a.ts');
    });

    it('flags a dream-exposed source file via target field', () => {
      const ex = empty(); ex.exposedSources.add('src/b.ts');
      expect(exclusionReason(ex, { commit: 'x', target: 'src/b.ts' })).toBe('dream-exposed source file src/b.ts');
    });

    it('flags derived-from when base prefix-matches an exposed commit (commit starts with base)', () => {
      const ex = empty(); ex.exposedCommits.add('abc1234567890');
      expect(exclusionReason(ex, { commit: 'other', base: 'abc1234' })).toBe('derived from dream-exposed commit abc1234');
    });

    it('flags derived-from when base prefix-matches an exposed commit (base starts with commit)', () => {
      const ex = empty(); ex.exposedCommits.add('abcdefg');
      expect(exclusionReason(ex, { commit: 'other', base: 'abcdefghij' })).toBe('derived from dream-exposed commit abcdefghij');
    });

    it('does not flag derived-from for short commits (< 7 chars)', () => {
      const ex = empty(); ex.exposedCommits.add('ab');
      expect(exclusionReason(ex, { commit: 'x', base: 'abcdefg' })).toBeNull();
    });

    it('flags a derived run id in the exposed runs set', () => {
      const ex = empty(); ex.exposedRuns.add('run-42');
      expect(exclusionReason(ex, { commit: 'x', run_id: 'run-42' })).toBe('derived from dream-exposed run run-42');
    });

    it('prioritises frozen over tg over trialAttempted over exposedCommits', () => {
      const ex = empty();
      ex.frozen.add('c'); ex.tg.add('c'); ex.trialAttempted.add('c'); ex.exposedCommits.add('c');
      expect(exclusionReason(ex, { commit: 'c' })).toBe('already frozen in a holdout epoch');
      ex.frozen.delete('c');
      expect(exclusionReason(ex, { commit: 'c' })).toBe('TG-001 task key');
      ex.tg.delete('c');
      expect(exclusionReason(ex, { commit: 'c' })).toBe('attempted in a genome trial');
      ex.trialAttempted.delete('c');
      expect(exclusionReason(ex, { commit: 'c' })).toBe('dream-exposed commit');
    });
  });

  describe('resolveHoldoutSize', () => {
    it('returns default 20 when neither env nor manifest is set', () => {
      expect(resolveHoldoutSize({})).toEqual({ ok: true, size: 20, source: 'default' });
    });

    it('reads from env when only HOLDOUT_SIZE is set', () => {
      expect(resolveHoldoutSize({ HOLDOUT_SIZE: '50' })).toEqual({ ok: true, size: 50, source: 'env' });
    });

    it('treats empty-string env as unset and falls back to default', () => {
      expect(resolveHoldoutSize({ HOLDOUT_SIZE: '' })).toEqual({ ok: true, size: 20, source: 'default' });
    });

    it('reads from manifest when only manifestSize is set', () => {
      expect(resolveHoldoutSize({}, 30)).toEqual({ ok: true, size: 30, source: 'manifest' });
    });

    it('prefers manifest over env when both are the same value', () => {
      expect(resolveHoldoutSize({ HOLDOUT_SIZE: '40' }, 40)).toEqual({ ok: true, size: 40, source: 'manifest' });
    });

    it('errors when env and manifest conflict', () => {
      const r = resolveHoldoutSize({ HOLDOUT_SIZE: '40' }, 50);
      expect(r.ok).toBe(false);
      if (!r.ok) expect(r.reason).toContain('conflicts');
    });

    it('rejects non-integer values', () => {
      expect(resolveHoldoutSize({ HOLDOUT_SIZE: 'abc' }).ok).toBe(false);
      expect(resolveHoldoutSize({}, 1.5).ok).toBe(false);
    });

    it('rejects values below MIN or above MAX', () => {
      expect(resolveHoldoutSize({ HOLDOUT_SIZE: '5' }).ok).toBe(false);
      expect(resolveHoldoutSize({ HOLDOUT_SIZE: '999' }).ok).toBe(false);
      expect(resolveHoldoutSize({}, 5).ok).toBe(false);
      expect(resolveHoldoutSize({}, 999).ok).toBe(false);
    });

    it('accepts boundary values MIN and MAX', () => {
      expect(resolveHoldoutSize({ HOLDOUT_SIZE: String(HOLDOUT_SIZE_MIN) })).toEqual({ ok: true, size: 10, source: 'env' });
      expect(resolveHoldoutSize({}, HOLDOUT_SIZE_MAX)).toEqual({ ok: true, size: 200, source: 'manifest' });
    });
  });
});

import { describe, it, expect } from 'vitest';
import Database from 'better-sqlite3';
import { rankNeedsYou, type InboxRequeue, type InboxLabel } from '../services/decisions-inbox';

const NOW = new Date('2026-10-13T00:00:00Z').getTime();
const D30_AGO = new Date(NOW - 30 * 86_400_000).toISOString();

function makeDb() {
  const db = new Database(':memory:');
  db.exec(`CREATE TABLE self_improvements (
    id TEXT PRIMARY KEY, title TEXT, status TEXT, updated_at TEXT,
    evidence_refs_json TEXT DEFAULT '[]', source TEXT DEFAULT '', created_at TEXT
  )`);
  return db;
}

function insertSettledRequeues(db: InstanceType<typeof Database>, count: number, verified: number) {
  for (let i = 1; i <= count; i++) {
    const status = i <= verified ? 'verified' : 'regressed';
    db.prepare(`INSERT INTO self_improvements (id, title, status, updated_at, evidence_refs_json)
      VALUES (?, ?, ?, ?, ?)`)
      .run(`rq-${i}`, `R${i}`, status, new Date(NOW - i * 86_400_000).toISOString(), JSON.stringify([`requeue-of:o${i}`]));
  }
}

describe('rankNeedsYou — Phase 3 shadow ranking', () => {
  it('returns an empty array when all inputs are empty', () => {
    const db = makeDb();
    expect(rankNeedsYou(db, [], [], [], NOW, { labelled: null, wrong: null })).toEqual([]);
    db.close();
  });

  it('scores requeue items with the measured verification rate (≥ MIN_N settled)', () => {
    const db = makeDb();
    insertSettledRequeues(db, 5, 3); // 3/5 = 0.6
    const rq: InboxRequeue[] = [{ id: 'r1', title: 'T', status: 'regressed', updated_at: D30_AGO, requeued_as: null, queue_class: 'operator' }];
    const out = rankNeedsYou(db, rq, [], [], NOW, { labelled: null, wrong: null });
    expect(out).toHaveLength(1);
    expect(out[0].kind).toBe('requeue');
    expect(out[0].expected_gain).toBe(0.6);
    expect(out[0].score).toBe(0.6); // 0.6 * 1 / 1
    db.close();
  });

  it('marks requeue INSUFFICIENT_EVIDENCE when fewer than 5 settled requeues exist', () => {
    const db = makeDb();
    insertSettledRequeues(db, 2, 2);
    const rq: InboxRequeue[] = [{ id: 'r1', title: 'T', status: 'regressed', updated_at: D30_AGO, requeued_as: null, queue_class: 'operator' }];
    const out = rankNeedsYou(db, rq, [], [], NOW, { labelled: null, wrong: null });
    expect(out[0].expected_gain).toBeNull();
    expect(out[0].score).toBeNull();
    expect(out[0].evidence[0]).toContain('INSUFFICIENT_EVIDENCE');
    db.close();
  });

  it('computes label gain as 1/(30−labelled) before the D5 gate', () => {
    const db = makeDb();
    const labels: InboxLabel[] = [{ id: 'l1', title: 'L', status: 'x', reason: '', verdict_at: D30_AGO, label: null }];
    const out = rankNeedsYou(db, [], labels, [], NOW, { labelled: 20, wrong: 1 });
    expect(out[0].kind).toBe('label');
    expect(out[0].expected_gain).toBe(0.1); // 1/10
    expect(out[0].score).toBe(0.1);
    db.close();
  });

  it('computes label gain as wrong/labelled after the D5 gate (≥ 30 labels)', () => {
    const db = makeDb();
    const labels: InboxLabel[] = [{ id: 'l1', title: 'L', status: 'x', reason: '', verdict_at: D30_AGO, label: null }];
    const out = rankNeedsYou(db, [], labels, [], NOW, { labelled: 40, wrong: 2 });
    expect(out[0].expected_gain).toBe(0.05); // 2/40
    expect(out[0].score).toBe(0.05);
    db.close();
  });

  it('returns null gain when d5 counts are unavailable', () => {
    const db = makeDb();
    const labels: InboxLabel[] = [{ id: 'l1', title: 'L', status: 'x', reason: '', verdict_at: D30_AGO, label: null }];
    const out = rankNeedsYou(db, [], labels, [], NOW, { labelled: null, wrong: null });
    expect(out[0].expected_gain).toBeNull();
    expect(out[0].evidence[0]).toContain('INSUFFICIENT_EVIDENCE');
    db.close();
  });

  it('always marks memory_review items as INSUFFICIENT_EVIDENCE with null score', () => {
    const db = makeDb();
    const mem = [{ id: 'm1', title: 'M', content: '', memory_type: 'rule', status: 'review_required', created_at: D30_AGO }];
    const out = rankNeedsYou(db, [], [], mem, NOW, { labelled: null, wrong: null });
    expect(out[0].kind).toBe('memory_review');
    expect(out[0].expected_gain).toBeNull();
    expect(out[0].score).toBeNull();
    db.close();
  });

  it('sorts measured items by score descending before INSUFFICIENT_EVIDENCE items', () => {
    const db = makeDb();
    insertSettledRequeues(db, 5, 5); // rate = 1.0
    const rq: InboxRequeue[] = [{ id: 'r1', title: 'High', status: 'regressed', updated_at: D30_AGO, requeued_as: null, queue_class: 'operator' }];
    const mem = [{ id: 'm1', title: 'Low', content: '', memory_type: 'rule', status: 'candidate', created_at: D30_AGO }];
    const out = rankNeedsYou(db, rq, [], mem, NOW, { labelled: null, wrong: null });
    expect(out).toHaveLength(2);
    expect(out[0].kind).toBe('requeue');   // score 1.0 first
    expect(out[0].score).toBe(1);
    expect(out[1].kind).toBe('memory_review'); // null score last
    db.close();
  });

  it('applies per-kind reversibility and operator_minutes assumptions', () => {
    const db = makeDb();
    const labels: InboxLabel[] = [{ id: 'l1', title: 'L', status: 'x', reason: '', verdict_at: D30_AGO, label: null }];
    const out = rankNeedsYou(db, [], labels, [], NOW, { labelled: 29, wrong: 0 });
    expect(out[0].reversibility).toBe(1);       // label assumption
    expect(out[0].operator_minutes).toBe(1);
    expect(out[0].evidence[1]).toContain('assumed');
    db.close();
  });
});

import Database from 'better-sqlite3';
import { afterEach, describe, expect, it } from 'vitest';
import { loadRecords, windowStarts, type WindowId } from '../services/usage-accounts';

const NOW = Date.parse('2026-10-18T12:00:00Z');
const ago = (h: number) => new Date(NOW - h * 3_600_000).toISOString();

function makeDb() {
  const d = new Database(':memory:');
  d.exec(`CREATE TABLE llm_model_calls (id INTEGER PRIMARY KEY AUTOINCREMENT, consumer TEXT NOT NULL, model TEXT NOT NULL, ok INTEGER NOT NULL, latency_ms INTEGER,
      out_chars INTEGER, shadow INTEGER NOT NULL DEFAULT 0, agree INTEGER, provider TEXT, tokens_in INTEGER, tokens_out INTEGER, task_kind TEXT, run_id TEXT, status TEXT,
      attempts INTEGER, purpose TEXT, experiment_id TEXT, cost_basis TEXT, list_price_cost REAL, marginal_cost REAL, created_at TEXT NOT NULL);
    CREATE TABLE loop_runs (id TEXT PRIMARY KEY, loop_name TEXT NOT NULL);
    CREATE TABLE worker_leases (id TEXT PRIMARY KEY, loop_run_id TEXT NOT NULL, role TEXT NOT NULL, runtime TEXT NOT NULL, status TEXT NOT NULL,
      metadata TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL);
    CREATE TABLE system_state (key TEXT PRIMARY KEY, value TEXT NOT NULL, updated_at TEXT NOT NULL);`);
  return d;
}

const dbs: Database.Database[] = [];
afterEach(() => { for (const d of dbs.splice(0)) d.close(); });
const fresh = () => { const d = makeDb(); dbs.push(d); d.prepare("INSERT INTO loop_runs VALUES ('run-1', 'self-improvement')").run(); return d; };

const call = (d: Database.Database, c: Record<string, unknown>) => d.prepare(
  `INSERT INTO llm_model_calls (consumer, model, ok, provider, tokens_in, tokens_out, status, purpose, cost_basis, list_price_cost, created_at)
   VALUES (@consumer, @model, @ok, @provider, @tokens_in, @tokens_out, @status, @purpose, @cost_basis, @list_price_cost, @created_at)`)
  .run({ ok: 1, provider: null, tokens_in: null, tokens_out: null, status: 'ok', purpose: null, cost_basis: null, list_price_cost: null, ...c });

let n = 0;
const lease = (d: Database.Database, runtime: string, meta: Record<string, unknown>, at: string, role = 'maker', status = 'completed') =>
  d.prepare('INSERT INTO worker_leases (id, loop_run_id, role, runtime, status, metadata, created_at) VALUES (?, ?, ?, ?, ?, ?, ?)')
    .run(`l${++n}`, 'run-1', role, runtime, status, JSON.stringify(meta), at);

describe('windowStarts', () => {
  it('returns UTC calendar boundaries for today and month, and rolling offsets for 5h and 7d', () => {
    const s = windowStarts(NOW);
    expect(s['5h']).toBe(NOW - 5 * 3_600_000);
    expect(s['7d']).toBe(NOW - 7 * 86_400_000);
    expect(s.today).toBe(Date.UTC(2026, 9, 18));
    expect(s.month).toBe(Date.UTC(2026, 9, 1));
  });

  it('crosses a UTC day/month boundary correctly', () => {
    const justAfter = Date.parse('2026-03-01T00:30:00Z');
    const s = windowStarts(justAfter);
    expect(s.today).toBe(Date.UTC(2026, 2, 1));
    expect(s.month).toBe(Date.UTC(2026, 2, 1));
  });

  it('exposes exactly the four documented window ids', () => {
    const s = windowStarts(NOW);
    expect(Object.keys(s).sort()).toEqual(['5h', '7d', 'month', 'today'] as unknown as string[]);
    for (const k of Object.keys(s) as WindowId[]) expect(typeof s[k]).toBe('number');
  });
});

describe('loadRecords', () => {
  it('returns empty records and ok sources for an empty database', () => {
    const d = fresh();
    const { records, sources } = loadRecords(d, ago(24));
    expect(records).toEqual([]);
    expect(sources).toEqual({ llm_model_calls: 'ok', worker_leases: 'ok' });
  });

  it('normalises llm_model_calls rows into UsageRecords, marking mirrors and limit hits', () => {
    const d = fresh();
    call(d, { consumer: 'panel', model: 'kimi-k3:cloud', provider: 'ollama', tokens_in: 100, tokens_out: 20, purpose: 'panel:review', created_at: ago(1) });
    call(d, { consumer: 'maker', model: 'ollama/kimi-k3', provider: 'opencode', tokens_in: 5000, created_at: ago(1) });
    call(d, { consumer: 'panel', model: 'kimi-k3:cloud', provider: 'ollama', ok: 0, status: 'you have reached your weekly usage limit', created_at: ago(2) });
    const { records, sources } = loadRecords(d, ago(24));
    expect(sources).toEqual({ llm_model_calls: 'ok', worker_leases: 'ok' });
    expect(records).toHaveLength(3);
    const panel = records.find((r) => r.consumer === 'panel:review')!;
    expect(panel.account).toBe('ollama_cloud');
    expect(panel.tokens).toBe(120);
    expect(panel.mirror).toBe(false);
    expect(panel.limit_hit).toBe(false);
    const mirror = records.find((r) => r.consumer === 'maker')!;
    expect(mirror.mirror).toBe(true);
    const failed = records.find((r) => !r.ok)!;
    expect(failed.limit_hit).toBe(true);
    expect(failed.error).toMatch(/weekly usage limit/);
  });

  it('counts tokens as null when both tokens_in and tokens_out are null', () => {
    const d = fresh();
    call(d, { consumer: 'panel', model: 'glm-5.3', provider: 'ollama', created_at: ago(1) });
    const { records } = loadRecords(d, ago(24));
    expect(records[0].tokens).toBeNull();
  });

  it('normalises worker_leases rows and skips mock/manual runtimes', () => {
    const d = fresh();
    lease(d, 'opencode', { model: 'ollama/kimi-k3', token_accounting: { total_tokens: 5000, model_id: 'ollama/kimi-k3' } }, ago(1));
    lease(d, 'claude', { subscription_auth: 'max' }, ago(2));
    lease(d, 'remote', {}, ago(2), 'checker');
    lease(d, 'manual', {}, ago(1));
    const { records } = loadRecords(d, ago(24));
    const accounts = records.map((r) => r.account).sort();
    expect(accounts).toEqual(['claude_max', 'local_workstation', 'ollama_cloud']);
    const ollama = records.find((r) => r.account === 'ollama_cloud')!;
    expect(ollama.tokens).toBe(5000);
    expect(ollama.consumer).toMatch(/^lease:maker:self-improvement$/);
    expect(ollama.provider).toBe('lease:opencode');
  });

  it('flags a subscription limit hit on a lease via subscription_limit_hit_at', () => {
    const d = fresh();
    lease(d, 'claude', { subscription_auth: 'max', subscription_limit_hit_at: ago(1), token_accounting: { total_tokens: 10 } }, ago(1), 'maker', 'failed');
    const { records } = loadRecords(d, ago(24));
    const r = records.find((x) => x.account === 'claude_max')!;
    expect(r.limit_hit).toBe(true);
    expect(r.limit_at).toBe(Date.parse(ago(1)));
    expect(r.error).toMatch(/subscription_limit/);
  });

  it('reports a source as missing when its table is absent', () => {
    const d = fresh();
    d.exec('DROP TABLE worker_leases');
    const { sources, records } = loadRecords(d, ago(24));
    expect(sources).toEqual({ llm_model_calls: 'ok', worker_leases: 'missing' });
    expect(records).toEqual([]);
  });

  it('only returns rows at or after the since cutoff', () => {
    const d = fresh();
    call(d, { consumer: 'panel', model: 'kimi-k3:cloud', provider: 'ollama', created_at: ago(48) });
    call(d, { consumer: 'panel', model: 'kimi-k3:cloud', provider: 'ollama', tokens_in: 5, created_at: ago(1) });
    const { records } = loadRecords(d, ago(24));
    expect(records).toHaveLength(1);
    expect(records[0].tokens).toBe(5);
  });
});

import { describe, expect, it } from 'vitest';
import { quarantineState, ledgerState, PARSE_OR_SCHEMA } from '../services/panel-attempt-metrics';

describe('quarantineState', () => {
  it('classifies an empty model response as GENERATION_FAILED', () => {
    expect(quarantineState('generation failed: empty model response')).toBe('GENERATION_FAILED');
  });

  it('classifies an empty model response with trailing detail as GENERATION_FAILED', () => {
    expect(quarantineState('generation failed: empty model response after 3 retries')).toBe('GENERATION_FAILED');
  });

  it('classifies a non-empty generation failure as INFRA_FAILED', () => {
    expect(quarantineState('generation failed: connection reset by peer')).toBe('INFRA_FAILED');
  });

  it('classifies a timeout-style generation failure as INFRA_FAILED', () => {
    expect(quarantineState('generation failed: provider returned 500')).toBe('INFRA_FAILED');
  });

  it('classifies a parse error ("no JSON object in the answer") as PARSE_FAILED', () => {
    expect(quarantineState('no JSON object in the answer')).toBe('PARSE_FAILED');
  });

  it('classifies a parse error ("answer is not valid JSON") as PARSE_FAILED', () => {
    expect(quarantineState('answer is not valid JSON')).toBe('PARSE_FAILED');
  });

  it('classifies a parse error ("answer is not a JSON object") as PARSE_FAILED', () => {
    expect(quarantineState('answer is not a JSON object')).toBe('PARSE_FAILED');
  });

  it('classifies a schema error as SCHEMA_INVALID', () => {
    expect(quarantineState('stance must be one of support|oppose|uncertain|needs_evidence (got null)')).toBe('SCHEMA_INVALID');
  });

  it('classifies a confidence schema error as SCHEMA_INVALID', () => {
