    db.prepare(`INSERT INTO worker_leases (id, loop_run_id, role, runtime, status, metadata) VALUES (?, ?, 'maker', 'opencode', 'completed', ?)`)
      .run('lease-1', 'run-1', JSON.stringify({ deterministic_checks: [{ name: 'type-check', exit_status: 2 }] }));
